//! As ferramentas como o MCP as anuncia: nome, descrição (o que a IA lê para decidir) e o formato dos argumentos.

use serde_json::{json, Value};

const PONTO: &str = "ponto [x, y]";

fn def(nome: &str, descricao: &str, propriedades: &Value, obrigatorios: &[&str]) -> Value {
    json!({ "name": nome, "description": descricao, "inputSchema": { "type": "object", "properties": propriedades, "required": obrigatorios } })
}

fn pt() -> Value {
    json!({ "type": "array", "items": { "type": "number" }, "minItems": 2, "maxItems": 2, "description": PONTO })
}

fn janela() -> Value {
    json!({ "type": "object", "properties": { "x1": { "type": "number" }, "y1": { "type": "number" }, "x2": { "type": "number" }, "y2": { "type": "number" } }, "required": ["x1", "y1", "x2", "y2"], "description": "retângulo do desenho, em coordenadas do desenho" })
}

fn filtros() -> Value {
    json!({
        "tipo": { "type": "string", "enum": ["linha", "polilinha", "circulo", "arco", "texto", "ponto", "hachura", "bloco"] },
        "camada": { "type": "string" },
        "ids": { "type": "array", "items": { "type": "integer" } },
        "janela": janela(),
        "modo": { "type": "string", "enum": ["dentro", "toca"], "description": "com `janela`: `dentro` = só o que cabe inteiro (padrão); `toca` = basta tocar" }
    })
}

/// Os arquivos e o estado geral.
fn de_arquivo() -> Vec<Value> {
    vec![
        def("cad_novo", "Começa um desenho em branco (descarta o atual). Sempre pergunte/escolha a unidade: as coordenadas são números puros e a unidade diz o que eles significam. Convenção: X para a direita, Y para cima, ângulos em graus anti-horário a partir do eixo X.", &json!({ "unidade": { "type": "string", "enum": ["mm", "cm", "m"] } }), &["unidade"]),
        def("cad_abrir", "Abre um arquivo `.dxf`, `.fcdz`, `.fct` (formato compacto) ou nuvem de pontos (`.xyz`, `.pts`, `.csv`, `.txt`) do disco no lugar do desenho atual. Nuvens de pontos são automaticamente convertidas em levantamento topográfico completo com curvas de nível e TIN. Devolve avisos do que não foi possível ler.", &json!({ "caminho": { "type": "string" } }), &["caminho"]),
        def("cad_salvar", "Grava o desenho em `.dxf`, `.fcdz` ou `.fct` (pela extensão). Sem `caminho`, grava onde foi aberto. Não sobrescreve arquivo existente sem `sobrescrever: true`. Com `verificar_checklist: true` ou `dominio: \"eletrica\"|\"arquitetura\"|\"hidraulica\"`, valida os requisitos mínimos do domínio antes de salvar e BLOQUEIA se houverem pendências.", &json!({ "caminho": { "type": "string" }, "sobrescrever": { "type": "boolean" }, "verificar_checklist": { "type": "boolean" }, "dominio": { "type": "string", "enum": ["eletrica", "arquitetura", "hidraulica", "geral"] }, "limite": { "type": "integer", "description": "com `leiaute`: quantos problemas listar por tipo (padrão 40; a contagem é sempre a total)" }, "leiaute": { "type": "boolean", "description": "confere em TEXTO o que só a imagem mostrava: texto sobre texto/linha, texto fora da folha ou entre duas folhas, texto de cabeça para baixo (devolve id e posição; peça cad_ver só onde houver problema)" } }), &[]),
        def("cad_converter", "Converte um arquivo em outro **sem** passar pelo desenho aberto nem gastar tokens: DXF/FCDZ → `.fct` (texto compacto, muito menor) e o contrário. Devolve os tamanhos antes e depois.", &json!({ "origem": { "type": "string" }, "destino": { "type": "string" }, "sobrescrever": { "type": "boolean" } }), &["origem", "destino"]),
        def("cad_pdf", "Grava o desenho em PDF VETORIAL (zoom sem perder nitidez; linha fina em fio de cabelo), uma página por folha (blocos `FOLHA-n` de cad_folha e retângulos fechados da camada FOLHA; sem folha, o desenho inteiro). `papel` A4, A3 (padrão), A2, A1, A0, 2A0, 4A0, 8A0, 16A0 FOLHA (tamanho da folha, 1 unidade = 1 mm) ou auto (cada página no papel da própria folha: A0 e A1 no mesmo arquivo); `orientacao` automatica|horizontal|vertical; `cores` true mantém as cores da tela (senão preto sobre branco); `folhas` [índices] escolhe páginas; não sobrescreve sem `sobrescrever: true`.", &json!({ "caminho": { "type": "string" }, "papel": { "type": "string" }, "orientacao": { "type": "string", "enum": ["automatica", "horizontal", "vertical"] }, "cores": { "type": "boolean" }, "folhas": { "type": "array", "items": { "type": "integer" } }, "sobrescrever": { "type": "boolean" } }), &["caminho"]),
        def("cad_projeto", "FUNIL DE PROJETO — use SÓ quando o usuário pedir um PROJETO (várias folhas, quadros, legendas: ex. \"gere um projeto luminotécnico\"). Pedido simples (desenhe um círculo, mova, apague) NÃO passa por aqui: chame direto a ferramenta de desenho. `acao: iniciar` devolve a primeira pergunta e as opções (elétrica, civil, ferroviário); PERGUNTE ao usuário e chame `escolher` com `caminho` (ex. [\"eletrica\", \"luminotecnico\"]); repita até receber a RECEITA: o que perguntar antes, as regras e as fases com os itens obrigatórios e a ferramenta de cada um. `acao: status` com o mesmo `caminho` confere cada item contra o desenho aberto (feito/pendente/manual) e diz o `proximo` passo e se está `pronto_para_entregar`. Chame `status` ao fim de cada fase e antes de entregar; não entregue com obrigatório pendente sem dizer ao usuário. Escolher `outra` abre um projeto sem receita (pergunte e proponha as folhas).", &json!({ "acao": { "type": "string", "enum": ["iniciar", "escolher", "status"] }, "caminho": { "type": "array", "items": { "type": "string" }, "description": "as escolhas já feitas, da raiz para a folha (ex. eletrica, luminotecnico)" } }), &[]),
        def("cad_resumo", "Visão geral barata (comece por aqui): unidade, extensão (caixa do desenho), quantas entidades por tipo e por camada, camadas, arquivo, se há alterações não salvas.", &json!({}), &[]),
        def("cad_modo", "Liga/desliga o MODO PROJETO (`projeto: true|false`; sem argumento só informa). Use ao GERAR um projeto grande (pranchas a partir de dados, cad_lote grande): cad_ver passa a render 800 px sem grade/rótulos, para o contexto não inchar com imagens. No uso normal (o usuário pede para ver, mexer, perguntar) deixe desligado.", &json!({ "projeto": { "type": "boolean" } }), &[]),
        def("cad_desfazer", "Desfaz o último passo (cada chamada de criar/editar/hachurar é um passo só). Com `refazer: true`, refaz.", &json!({ "refazer": { "type": "boolean" } }), &[]),
    ]
}

/// As que dão noção de espaço: ver, listar, medir, regiões, verificar, texto compacto.
fn de_consulta() -> Vec<Value> {
    let ver = json!({
        "janela": janela(),
        "largura": { "type": "integer", "description": "largura da imagem em pixels (300 a 2400; padrão 1000, 800 no modo projeto)" },
        "rotulos": { "type": "boolean", "description": "escreve o #id de cada entidade ao lado dela (padrão sim; não no modo projeto)" },
        "grade": { "type": "boolean", "description": "grade com números nas bordas (padrão sim; não no modo projeto)" },
        "arquivo": { "type": "string", "description": "caminho .png: grava a imagem no disco e devolve só o caminho e a janela (a imagem não entra na conversa, economiza contexto)" },
        "destacar": { "type": "array", "items": { "type": "integer" }, "description": "ids a realçar em azul" },
        "isometria": { "type": "boolean", "description": "renderiza em perspectiva isométrica 3D (rotacao_x=55, rotacao_z=45 por padrão)" },
        "rotacao_x": { "type": "number", "description": "inclinação vertical da câmera 3D em graus (0 = topo 2D, 55 = isométrica, 90 = perfil lateral)" },
        "rotacao_z": { "type": "number", "description": "órbita horizontal da câmera 3D em graus (0 = norte para cima, 45 = sudoeste-nordeste)" }
    });
    let perto = json!({ "type": "object", "properties": { "ponto": pt(), "raio": { "type": "number" } }, "required": ["ponto", "raio"], "description": "só o que está a até `raio` do ponto (traz `distancia` e `direcao_do_ponto`)" });
    let mut ent = filtros();
    ent["perto"] = perto;
    ent["limite"] = json!({ "type": "integer", "description": "máximo de entidades (padrão 100, até 500)" });
    let mut exp = filtros();
    exp["com_ids"] = json!({ "type": "boolean", "description": "escreve @id em cada linha, para poder editar depois (padrão não: mais barato)" });
    vec![
        def("cad_ver", "Uma IMAGEM do desenho (PNG) para você enxergar: grade com coordenadas nas bordas, eixos x/y, barra de escala e o #id de cada entidade. Sem `janela` mostra tudo; com `janela` dá zoom numa região. Depois de desenhar, confira com isto. A resposta diz a janela exata e quantas unidades vale cada pixel.", &ver, &[]),
        def("cad_entidades", "Lista entidades com medidas exatas (comprimento, área, centro, raio, ângulo, caixa…), filtrando por tipo, camada, ids, janela ou proximidade de um ponto. É a forma de saber ONDE as coisas estão e QUANTO medem.", &ent, &[]),
        def("cad_exportar", "O desenho em TEXTO COMPACTO (uma linha por objeto: `L x1 y1 x2 y2`, `C cx cy r`, `R x y l a`…), várias vezes menor que DXF (e o DXF de outros programas, como o do AutoCAD, é ainda mais pesado). Use para ler o desenho inteiro ou uma parte gastando poucos tokens. Blocos são abertos em formas soltas.", &exp, &[]),
        def("cad_importar", "Cria formas a partir de texto compacto (o mesmo de `cad_exportar`), vindo em `texto` ou de um `.fct` do disco em `caminho` (acrescenta ao desenho aberto, sem reabrir; grande = use `caminho`, não cole na conversa). Uma chamada = um passo de desfazer. Com `substituir: true`, apaga o desenho antes. Linhas 3D: `camera iso|obliqua|az=20 el=35 escala=2 origem=x,y` e depois `L3 x y z x y z` ou `P3 x y z …` (projetadas para 2D ao importar). Erros dizem a linha.", &json!({ "texto": { "type": "string" }, "caminho": { "type": "string", "description": "arquivo .fct a acrescentar (em vez de `texto`)" }, "substituir": { "type": "boolean" } }), &[]),
        def("cad_medir", "Medições exatas. `{de, para}` (cada um ponto [x,y] ou {id}) → distância, dx, dy, ângulo; entre entidades, a distância mínima. `{pontos:[…]}` → área e perímetro do polígono. `{vertice, a, b}` → ângulo entre as duas direções. `{texto, altura}` → largura que o texto ocupa (mesma métrica do PDF).", &json!({ "texto": { "type": "string" }, "altura": { "type": "number" }, "de": {}, "para": {}, "pontos": { "type": "array", "items": pt() }, "vertice": pt(), "a": pt(), "b": pt() }), &[]),
        def("cad_regioes", "As áreas FECHADAS que os traços formam (salas, peças), com área, perímetro, centro e os textos que caem dentro; `area_util` já desconta vãos. Com `ponto`, só a que contém o ponto (o que uma hachura preencheria). Se uma região esperada não aparece, há abertura no contorno: use cad_verificar.", &json!({ "ponto": pt(), "limite": { "type": "integer" } }), &[]),
        def("cad_verificar", "Procura defeitos: entidades de comprimento zero, duplicadas e FOLGAS (extremidade que quase toca outra forma sem tocar). Com `dominio: \"eletrica\"|\"arquitetura\"|\"hidraulica\"`, roda também o CHECKLIST de requisitos mínimos de construção.", &json!({ "tolerancia": { "type": "number", "description": "distância máxima que conta como folga (padrão 0,2% da diagonal do desenho)" }, "dominio": { "type": "string", "enum": ["eletrica", "arquitetura", "hidraulica", "geral"] } }), &[]),
        def("cad_exemplos", "MODELOS E EXEMPLOS DE PROJETOS — devolve modelos de referência para dar contexto sobre como estruturar projetos (arquitetura, elétrica, hidráulica, estrutural, ferrovia, mecânica). Sem `nome`, lista os modelos disponíveis; com `nome` (ex.: 'arquitetura', 'eletrica', 'ferrovia'), devolve a especificação técnica de camadas ACI, folhas e o código em `cad_lote`.", &json!({ "nome": { "type": "string" } }), &[]),
    ]
}

/// As que mudam o desenho.
fn de_edicao() -> Vec<Value> {
    let forma = json!({ "type": "object", "properties": { "tipo": { "type": "string", "enum": ["linha", "retangulo", "poligono", "polilinha", "circulo", "arco", "hachura", "texto"] } }, "required": ["tipo"], "description": "linha: {a,b} ou {de,distancia,angulo}; retangulo: {canto1,canto2} ou {canto,largura,altura,rotacao?} (+ raio: cantos arredondados); hachura: {pontos} ou {contornos:[[pts],[pts]]} (o 2º em diante são ilhas), padrao (solida, concreto, terra…), escala; poligono: {centro,raio,lados,rotacao?}; polilinha: {pontos,fechada?}; circulo: {centro,raio}; arco: {centro,raio,inicio,fim} (graus, anti-horário) ou {p1,p2,p3}; texto: {ponto,altura,conteudo,rotacao?}" });
    let mut ed = filtros();
    ed["operacao"] = json!({ "type": "string", "enum": ["mover", "copiar", "girar", "escala", "espelhar", "apagar", "propriedades", "texto"], "description": "texto: {conteudo?, altura?} troca o texto (e/ou a altura) dos textos escolhidos; mover/copiar: {dx,dy} ou {de,para} (copiar aceita `quantidade`); girar: {base,graus,copiar?}; escala: {base,fator}; espelhar: {p1,p2,manter_original?=true}; propriedades: {para_camada?, para_cor? (#RRGGBB ou por_camada)}" });
    for c in ["dx", "dy", "graus", "fator", "quantidade"] {
        ed[c] = json!({ "type": "number" });
    }
    ed["altura"] = json!({ "type": "number", "description": "operacao texto: nova altura do texto" });
    ed["conteudo"] = json!({ "type": "string", "description": "operacao texto: o novo conteúdo" });
    for c in ["base", "p1", "p2", "de", "para"] {
        ed[c] = pt();
    }
    vec![
        def("cad_criar", "Desenha uma ou mais formas de uma vez (um passo de desfazer). Coordenadas na unidade do desenho. `camada` (criada se não existir) e `cor` (#RRGGBB) valem para todas as formas da chamada. Confira depois com cad_ver.", &json!({ "formas": { "type": "array", "items": forma }, "camada": { "type": "string" }, "cor": { "type": "string" } }), &["formas"]),
        def("cad_editar", "Transforma ou apaga entidades já existentes, escolhidas por `ids` ou por filtros (tipo, camada, janela). Entidades de camada bloqueada são puladas.", &ed, &["operacao"]),
        def("cad_camadas", "Camadas: `listar` (padrão), `criar` {nome, cor?, espessura?, tipo_linha?}, `atual` {nome}, `propriedade` {nome, ligada?, congelada?, bloqueada?, cor?, espessura?, tipo_linha?}. Espessura em mm (paredes ~0,5; eletroduto ~0,35); tipo_linha tracejada para tubulação no piso.", &json!({ "acao": { "type": "string", "enum": ["listar", "criar", "atual", "propriedade"] }, "nome": { "type": "string" }, "cor": { "type": "string" }, "ligada": { "type": "boolean" }, "congelada": { "type": "boolean" }, "bloqueada": { "type": "boolean" }, "espessura": { "type": "number", "description": "espessura de linha da camada em mm (0 = padrão); vale para os objetos \"por camada\"" }, "tipo_linha": { "type": "string", "enum": ["continua", "tracejada", "oculta", "eixo", "pontilhada", "fantasma"] } }), &[]),
        def("cad_hachurar", "Preenche a região fechada que contém `ponto` (contorno de linhas, arcos, polilinhas ou círculo). `solida` padrão sim; senão, linhas a 45°. `padrao` escolhe da biblioteca: solida, ansi31 (45°), ansi32 (aço), ansi37 (cruzada), horizontal, vertical, grade, pontos, concreto, areia, brita, terra, tijolo; `escala` (padrão 1) multiplica o espaço do padrão (maior = mais aberto). Falha se o contorno tem abertura.", &json!({ "ponto": pt(), "solida": { "type": "boolean" }, "padrao": { "type": "string", "description": "solida, ansi31, ansi32, ansi37, horizontal, vertical, grade, pontos, concreto, areia, brita, terra, tijolo" }, "escala": { "type": "number", "description": "multiplica o espaço do padrão (0,25 a 4)" } }), &["ponto"]),
        def("cad_folha", "FOLHAS (pranchetas) — a mesma do botão Inserir folha do aplicativo: moldura, marcas de centro, faixa de notas/legenda/revisões e carimbo, como um bloco `FOLHA-n` na escala do desenho. `acao`: `listar` (padrão: folhas, papéis e escalas), `inserir` {papel A4…16A0 (padrão A1), escala (denominador; sem ela usa a menor em que o desenho cabe), campos {cliente, fase, disciplina, titulo, subtitulo, numero, revisao, folha, divisoria}, origem:true (canto inferior esquerdo em 0,0) ou ponto [x,y]}, `escala` {indice, escala} (troca mantendo o centro da área útil), `ajustar` {indice} (menor escala em que o desenho todo cabe), `campos` {indice}, `campos_definir` {indice, campos}. A área útil de uma A1 vai de (35;109) a (821;574) mm de papel; a faixa de notas/legenda fica em y 10 a 99. Em desenho em mm a 1:1, a folha tem o tamanho do papel.", &json!({ "acao": { "type": "string", "enum": ["listar", "inserir", "escala", "ajustar", "campos", "campos_definir"] }, "papel": { "type": "string" }, "escala": { "type": "number" }, "indice": { "type": "integer" }, "campos": { "type": "object" }, "origem": { "type": "boolean" }, "ponto": pt() }), &[]),
        def("cad_contar", "CONTA objetos: `simbolos: true` (tomadas, interruptores, luzes… de cad_simbolo, por nome: para a lista de materiais) ou `igual_a` {id} (todos com o mesmo tipo e medida, por camada) ou `tipo` (retangulo | circulo | linha) + `medida` ({largura, altura} | {raio} | {comprimento}) + `tolerancia` (relativa, padrão 0,01) e `camada` opcional. Retângulo vale em qualquer giro e deitado ou em pé. `ids: N` devolve os N primeiros ids. Ex.: dormentes = tipo retangulo, medida {largura:0.24, altura:2}.", &json!({ "simbolos": { "type": "boolean" }, "igual_a": { "type": "integer" }, "tipo": { "type": "string", "enum": ["retangulo", "circulo", "linha"] }, "medida": { "type": "object" }, "tolerancia": { "type": "number" }, "camada": { "type": "string" }, "ids": { "type": "integer" } }), &[]),
    ]
}

/// Projeto elétrico (NBR 5444): símbolos prontos e eletroduto com condutores. Só para projeto elétrico.
fn de_eletrica() -> Vec<Value> {
    let simbolo = json!({
        "nome": { "type": "string", "description": "nome do símbolo (veja cad_simbolos): tomada_baixa|tomada_media|tomada_alta|tomada_piso|ponto_luz_teto|ponto_luz_embutido|arandela|ponto_luz_vapor_mercurio|interruptor_simples|interruptor_paralelo|interruptor_intermediario|interruptor_duas_secoes|quadro_geral_embutido|quadro_geral_aparente|quadro_parcial_embutido|quadro_parcial_aparente|caixa_telefone|caixa_medidor|caixa_passagem_piso|luz_multifilar|disjuntor|no_de_ligacao" },
        "ponto": pt(),
        "escala": { "type": "number", "description": "denominador da escala do desenho (50 = 1:50, padrão 50): o símbolo tem o tamanho de papel certo" },
        "parede": { "type": "string", "enum": ["norte", "sul", "leste", "oeste"], "description": "tomadas: de que lado do símbolo está a parede (ele aponta para o lado oposto)" },
        "rotacao": { "type": "number", "description": "giro em graus anti-horário (alternativa a `parede`); o texto continua na horizontal" },
        "quantidade": { "type": "integer", "description": "tomada: 1/2/3 = simples/dupla/tripla; luz: número de lâmpadas (vira 2x100W)" },
        "circuito": { "type": ["integer", "string"], "description": "número do circuito (na luz aparece como -4-)" },
        "comando": { "type": "string", "description": "letra minúscula do interruptor que comanda o ponto (a, b, c…)" },
        "potencia": { "type": ["number", "string"], "description": "100 vira 100W; ou texto como 600VA" },
        "altura_texto": { "type": "number", "description": "altura do texto em mm de papel (padrão 1,8)" },
        "encostar": { "type": "boolean", "description": "tomadas, interruptores e arandela: acha a parede desenhada mais próxima (até 1 m), põe o símbolo NA FACE dela e gira sozinho (dispensa `parede`)" },
        "bloco": { "type": "boolean", "description": "padrão sim: o símbolo vira UM bloco SIMB-<nome>-<n> (mover/apagar = uma entidade; cad_contar e cad_ramais o acham). false = formas soltas" },
        "camada": { "type": "string" },
        "cor": { "type": "string", "description": "#RRGGBB" }
    });
    let conduto = json!({ "type": "object", "properties": {
        "circuito": { "type": ["integer", "string"] },
        "tipo": { "type": "string", "enum": ["fase", "neutro", "retorno", "terra"] },
        "secao": { "type": "number", "description": "mm² (padrão 1,5)" },
        "quantidade": { "type": "integer", "description": "quantos condutores iguais (ex.: 2 fases)" }
    }, "required": ["tipo"] });
    let eletroduto = json!({
        "pontos": { "type": "array", "items": pt(), "minItems": 2, "description": "caminho do eletroduto, em coordenadas do desenho" },
        "condutores": { "type": "array", "items": conduto, "description": "o que passa dentro: um item por tipo/circuito (fase, neutro, retorno, terra)" },
        "tipo": { "type": "string", "enum": ["teto", "parede", "piso"], "description": "teto/parede = linha contínua; piso = tracejada (padrão teto)" },
        "diametro": { "type": "number", "description": "Ø em mm; sem ele, calcula pela ocupação de 40 %" },
        "terra": { "type": "boolean", "description": "acrescenta um condutor terra (padrão sim)" },
        "secao_terra": { "type": "number" },
        "escala": { "type": "number", "description": "denominador da escala (padrão 50)" },
        "posicao": { "type": "number", "description": "0 a 1: onde, ao longo do trecho mais comprido, ficam os traços (padrão 0,5)" },
        "rotulo": { "type": "boolean", "description": "escreve circuitos, seções e Ø (padrão sim)" },
        "curva": { "type": "number", "description": "só com 2 pontos: faz o eletroduto curvo, como no unifilar da NBR (0,1 a 0,3; + curva para a esquerda de a→b, − para a direita). Evita linhas retas cruzando a planta." },
        "espessura": { "type": "number", "description": "espessura da linha do eletroduto em mm (ex. 0,35), mais grossa que o resto" },
        "altura_texto": { "type": "number" },
        "camada": { "type": "string" },
        "cor": { "type": "string" }
    });
    vec![
        def("cad_simbolos", "PROJETO ELÉTRICO (NBR 5444) — use só se o projeto for elétrico. Lista a biblioteca de símbolos prontos (tomada baixa/média/alta/piso, ponto de luz, interruptores S/S3/S4, quadros, multifilar…) e o que cada um aceita.", &json!({}), &[]),
        def("cad_simbolo", "PROJETO ELÉTRICO (NBR 5444) — use só se o projeto for elétrico. Coloca um símbolo pronto pelo nome, no tamanho certo para a escala, com os rótulos (circuito, comando, potência). Exemplo: {nome:\"tomada_media\", ponto:[100,20], parede:\"sul\", circuito:3}. Um passo de desfazer.", &simbolo, &["nome", "ponto"]),
        def("cad_componentes", "BIBLIOTECA DE COMPONENTES (arquivos .fct prontos: disjuntor modular, DR, DPS, trilho, barras, caixa de quadro, transformador…). Lista o que existe com parâmetros e tamanho; `busca` filtra por texto. Use ANTES de desenhar qualquer equipamento elétrico: chamar o componente gasta muito menos que redesenhar.", &json!({ "busca": { "type": "string" } }), &[]),
        def("cad_parede", "ARQUITETURA: paredes CHEIAS com espessura e os vãos já abertos e desenhados (porta de giro com folha e arco, porta de correr, janela, passagem). É a base para cad_simbolo {encostar} e cad_ramais. Ex.: {paredes:[{de:[0,0], ate:[4,0], espessura:0.15, vaos:[{inicio:1.0, largura:0.8, tipo:\"porta\", dobradica:\"inicio\", abre:\"esquerda\"}]}]}. `inicio` = distância desde `de`; `abre` esquerda/direita olhando de `de` para `ate`. Um passo de desfazer.", &json!({
            "paredes": { "type": "array", "items": { "type": "object", "properties": {
                "de": pt(), "ate": pt(), "espessura": { "type": "number", "description": "na unidade do desenho (padrão 0,15 m)" },
                "vaos": { "type": "array", "items": { "type": "object", "properties": {
                    "inicio": { "type": "number" }, "largura": { "type": "number" },
                    "tipo": { "type": "string", "enum": ["porta", "correr", "janela", "passagem"] },
                    "dobradica": { "type": "string", "enum": ["inicio", "fim"] }, "abre": { "type": "string", "enum": ["esquerda", "direita"] }
                }, "required": ["inicio", "largura"] } }
            }, "required": ["de", "ate"] } },
            "espessura": { "type": "number", "description": "padrão para as paredes sem espessura" },
            "camada": { "type": "string", "description": "padrão ARQ-Paredes" },
            "camada_esquadrias": { "type": "string", "description": "padrão ARQ-Esquadrias" }
        }), &["paredes"]),
        def("cad_ambiente", "ARQUITETURA: escreve o nome e a área (m²) do ambiente no meio dele. `retangulo` [[x1,y1],[x2,y2]] ou `pontos` (contorno). Devolve a área.", &json!({
            "nome": { "type": "string" }, "retangulo": { "type": "array", "items": pt() }, "pontos": { "type": "array", "items": pt() },
            "ponto": pt(), "escala": { "type": "number" }, "altura_texto": { "type": "number", "description": "mm de papel (padrão 2,5)" }, "camada": { "type": "string", "description": "padrão ARQ-Textos" }
        }), &["nome"]),
        def("cad_ramais", "PROJETO ELÉTRICO: traça o ramal de UM ambiente DENTRO das paredes desenhadas (cad_parede): encadeia as tomadas e interruptores de cada trecho de parede, corta em cada porta/passagem e desce perpendicular do ponto de luz até a parede. Lê as tomadas, interruptores e luzes do desenho (blocos SIMB- de cad_simbolo). Avisa ponto em vão de porta ou solto no ambiente. Sem marcas de condutor (vão em NOTA).", &json!({
            "ambiente": { "type": "array", "items": pt(), "description": "[[x1,y1],[x2,y2]] pelos EIXOS das paredes do ambiente" },
            "alimentacao": { "type": "array", "items": pt(), "description": "pontos extras de onde o ramal pode sair (tronco, caixa), além das luzes" },
            "recuo": { "type": "number", "description": "distância do eixo da parede para dentro do ambiente (padrão 3 cm)" },
            "camada": { "type": "string", "description": "padrão EL-Condutos" }
        }), &["ambiente"]),
        def("cad_componente", "Coloca um COMPONENTE pronto da biblioteca (veja cad_componentes) com o canto inferior esquerdo em `ponto`, em milímetros reais. Exemplo: {nome:\"disjuntor_modular_2p\", ponto:[62,110], valores:{corrente:\"C25\", icc:\"6kA\"}}. `ampliacao` (padrão 1) e `rotacao` (graus) opcionais. Um passo de desfazer; funciona dentro de cad_lote.", &json!({ "nome": { "type": "string" }, "ponto": pt(), "valores": { "type": "object", "description": "parâmetros do componente {nome: valor}, os que cad_componentes mostra" }, "ampliacao": { "type": "number" }, "rotacao": { "type": "number" }, "camada": { "type": "string" } }), &["nome", "ponto"]),
        def("cad_eletroduto", "PROJETO ELÉTRICO (NBR 5444) — use só se o projeto for elétrico. Desenha um eletroduto (contínuo no teto/parede, tracejado no piso) com os traços dos condutores (fase cruza; neutro cruza com bandeira; retorno meio traço; terra meio traço com T), números dos circuitos em cima, seção embaixo e Ø. Um eletroduto compartilhado por vários circuitos é uma chamada só, com todos os condutores.", &eletroduto, &["pontos", "condutores"]),
        def("cad_luminotecnico", "PROJETO DE ILUMINAÇÃO — cálculo em Rust de um ambiente retangular: MÉTODO DOS LUMENS (índice do local K, fator de utilização, nº de luminárias, arranjo linhas × colunas que respeita e/hm, espaçamentos e distância da parede, iluminância média, potência instalada e W/m²) e GRADE DE ILUMINÂNCIA ponto a ponto (média, mínima, máxima e uniformidade, só luz direta, conservador). Dados: `ambiente: {comprimento, largura, pe_direito, plano_trabalho (0,8)}` em METROS, `iluminancia_lux`, `luminaria: {fluxo_lm, potencia_w, altura_montagem, fator_utilizacao (sem ele usa um típico genérico, avisa), expoente (1 = lambertiana)}`, `fator_manutencao` (0,8), `uniformidade_minima` (0,6), `espacamento_max_hm` (1,5), `arranjo: {linhas, colunas}` (para forçar), `grade_passo` (m; com ele devolve também os valores), `borda_m` (0,5: faixa junto às paredes fora da estatística, como a NBR ISO 8995-1). Devolve `posicoes_m` de cada luminária a partir do canto inferior esquerdo do ambiente (use para desenhar), `premissas` e `avisos`. Com `desenhar_mapa: {origem, camada (LUX)}` desenha o mapa de lux em faixas de cor (origem = canto inferior esquerdo do ambiente, em coordenadas do desenho) e devolve as `faixas` para a legenda. Não calcula luz natural nem reflexões: confirme com a fotometria do fabricante.", &json!({ "ambiente": { "type": "object" }, "iluminancia_lux": { "type": "number" }, "luminaria": { "type": "object" }, "fator_manutencao": { "type": "number" }, "uniformidade_minima": { "type": "number" }, "espacamento_max_hm": { "type": "number" }, "arranjo": { "type": "object" }, "grade_passo": { "type": "number" }, "borda_m": { "type": "number" }, "desenhar_mapa": { "type": "object" } }), &["ambiente", "iluminancia_lux", "luminaria"]),
        def("cad_carimbo", "CARIMBO E FAIXA DA FOLHA — devolve, em COORDENADAS DO DESENHO, onde ficam as caixas NOTAS, LEGENDA, RESPONSÁVEL TÉCNICO e a área útil da folha `indice` (use `origem` = canto superior esquerdo da caixa: x = min.x, y = max.y, e `escala` = a da folha, nos cad_texto_bloco/cad_tabela/cad_notas_padrao para pôr o conteúdo DENTRO delas, sem deixar caixa vazia nem texto solto ao lado). Com `linhas: [texto…]` (até 5) escreve na caixa do responsável técnico, ABAIXO da 1ª linha (que é o campo `responsavel` de cad_folha: ponha nele o projetista): CREA, ART, proprietário, área, data — o que os campos do carimbo não têm. `altura_texto` em mm de papel (2,0).", &json!({ "indice": { "type": "integer" }, "linhas": { "type": "array", "items": { "type": "string" } }, "altura_texto": { "type": "number" } }), &[]),
        def("cad_notas_padrao", "PROJETO ELÉTRICO — NOTAS NORMATIVAS prontas, numeradas em sequência, tiradas do que os projetos profissionais de referência trazem. `conjuntos`: geral (NBR 5410, NR-10, NBR 5444, cores dos condutores, aterramento das partes metálicas), aterramento (solda exotérmica, haste, profundidade), quadros (etiquetas, barreira, terminais, DR e DPS), iluminacao (NBR ISO/CIE 8995-1, fotometria), emergencia (NBR 10898). `eletroduto` e `fiacao` entram nas notas de \"não cotado\". Com `desenhar: {origem, largura, escala, altura_texto, titulo, colunas, altura_max, camada}` já escreve na folha (cad_texto_bloco). Confira as normas na edição vigente.", &json!({ "conjuntos": { "type": "array", "items": { "type": "string" } }, "eletroduto": { "type": "string" }, "fiacao": { "type": "string" }, "desenhar": { "type": "object" } }), &[]),
        def("cad_circuitos", "PROJETO ELÉTRICO — a LISTA DE CIRCUITOS como fonte única de um quadro. Você passa só os dados (`circuitos: [{id, descricao, tipo: iluminacao|tug|tue|outro, potencia_w, tensao: \"fn\"|\"ff\"|220, fp, comprimento_m, fase (R|S|T ou RS…; sem ela o motor equilibra), dr, agrupamento}]`, `quadro: {nome, tensao_fn (127), tensao_ff (220), fases (3), temperatura (30), limite_dv (4 %), alimentador_m, fator_demanda, dr_em_tomadas, agrupamento, disjuntor_minimo_a}; no circuito também `disjuntor_minimo_a``, `fatores_demanda: {iluminação: 1, TUG: 0,8…}`) e o Rust calcula: corrente de projeto, disjuntor padronizado, seção (NBR 5410, PVC 70 °C, método B1, com fatores de temperatura e agrupamento) pelo critério da capacidade e da queda de tensão, DR de 30 mA, distribuição e desequilíbrio das fases, alimentador (disjuntor geral, seção), demanda. Devolve `circuitos`, `totais`, `alimentador`, `demanda`, `premissas` e `avisos` (circuito que não fecha, fases desequilibradas). Com `desenhar: {quadro_de_cargas: {origem, escala}, demanda: {origem, escala}, unifilar: {origem, escala}}` desenha, dos MESMOS números, o quadro de cargas completo (Ib, seção, Iz, disjuntor, DR, dV parcial e total, status), o quadro de demanda e o unifilar (alimentação, disjuntor geral, barramento, uma saída por circuito com disjuntor, DR, seção, fase e carga). `origem` = canto superior esquerdo; `escala` faz as medidas valerem em mm de papel. Camadas: DI-Tabelas, DI-Linhas do diagrama, DI-Disjuntor, DI-Textos do diagrama. Limites e fatores de demanda são premissas (vêm em `premissas`): confira na norma/concessionária.", &json!({ "circuitos": { "type": "array", "items": { "type": "object" } }, "quadro": { "type": "object" }, "fatores_demanda": { "type": "object" }, "desenhar": { "type": "object" } }), &["circuitos"]),
    ]
}

/// O lote: dados + laços declarativos + expressões.
fn de_lote() -> Vec<Value> {
    let passo = json!({ "type": "object", "description": "UM destes: {ferramenta, argumentos, guardar?} | {definir:\"nome\", valor} | {para_cada, como?, indice?, faca:[passos]} | {repetir, como?, faca:[passos]} | {se, entao:[passos], senao?:[passos]} | {exigir, mensagem?}" });
    let props = json!({
        "dados": { "type": "object", "description": "variáveis de partida {nome: valor}: números, textos, listas, objetos (tabelas de pontos, circuitos…)" },
        "passos": { "type": "array", "items": passo },
        "retornar": { "type": "array", "items": { "type": "string" }, "description": "nomes de variáveis a devolver no resultado (as guardadas com `guardar` ou `definir`)" }
    });
    vec![def("cad_lote", "Executa MUITAS ferramentas numa chamada só, com DADOS e LAÇOS feitos pelo servidor (você manda os dados uma vez e o molde uma vez; não repita chamadas). Tudo ou nada: se um passo falha, nada é aplicado e o erro diz o passo e a volta (`passo [2].faca(volta 4)[0]: …`); se dá certo, é UM passo de desfazer. Passos: {ferramenta:\"cad_simbolo\", argumentos:{…}, guardar:\"nome\"} chama qualquer ferramenta (menos cad_ver/cad_novo/cad_abrir/cad_desfazer/cad_lote); {definir:\"x\", valor:\"=expr\"}; {para_cada:\"lista\" (nome de variável ou =expr), como:\"l\", indice:\"i\", faca:[…]}; {repetir:\"=n\", como:\"i\", faca:[…]}; {se:\"=cond\", entao:[…], senao:[…]}; {exigir:\"=cond\", mensagem:\"…\"} valida dados. Em qualquer valor de argumento: texto que começa com `=` é EXPRESSÃO e vira o valor (número, ponto, lista…); `${expr}` dentro de um texto é trocado pelo valor; `==` no começo escreve um `=` literal. Expressões: + - * / %, comparações, && || !, c ? a : b, índice l[0] (negativo = do fim), campo c.nome, lista [x, y]; contas com listas de números valem elemento a elemento ([1,2]+[10,20], [3,4]*2), então pontos se somam; + com texto junta. Funções: abs min max soma media arredondar(x,casas) piso teto raiz potencia sen cos tan atan2 (graus) dist(a,b) angulo(a,b) ponto_polar(o,ang,d) ponto_medio comprimento(caminho) deslocar(caminho,d) (paralela à esquerda; d<0 direita) intervalo(n) tamanho texto numero virgula(x,casas) se(c,a,b) juntar contem inverter soma_campo(lista,\"campo\") onde(lista,\"campo\",valor). Exemplo: {dados:{X:300,luzes:[[250,200,\"a\"]]}, passos:[{para_cada:\"luzes\", como:\"l\", faca:[{ferramenta:\"cad_simbolo\", argumentos:{nome:\"ponto_luz_teto\", ponto:\"=[X + l[0], l[1]]\", comando:\"=l[2]\", circuito:1}}]}]}. Devolve chamadas, voltas, entidades_novas e as variáveis pedidas em `retornar`. Limites: 50 mil chamadas, 200 mil voltas, 16 níveis. Gravar arquivo (cad_salvar) não é desfeito se um passo posterior falhar: deixe por último.", &props, &["passos"])]
}

/// Topografia: nuvem de pontos, triangulação Delaunay (TIN), curvas de nível e levantamento topográfico.
fn de_topografia() -> Vec<Value> {
    let topo = json!({
        "caminho": { "type": "string", "description": "caminho do arquivo de pontos (.xyz, .pts, .csv, .txt)" },
        "texto": { "type": "string", "description": "conteúdo de texto com os pontos (E,N,Z ou X,Y,Z delimitado por vírgula, ponto-e-vírgula, tab ou espaço)" },
        "equidistancia": { "type": "number", "description": "intervalo de cota entre curvas de nível em metros (ex.: 1.0 ou 0.5; calcula automático se omitido)" },
        "passo_mestra": { "type": "integer", "description": "a cada quantas curvas uma é mestra com espessura maior e cota inteira (padrão 5)" },
        "max_aresta": { "type": "number", "description": "comprimento máximo da aresta da malha TIN em metros (remove triângulos espúrios nas bordas côncavas)" },
        "incluir_tin": { "type": "boolean", "description": "gera a malha triangular TIN na camada TOPOGRAFIA_TIN (padrão true)" },
        "incluir_pontos": { "type": "boolean", "description": "insere marcadores em forma de cruz para cada ponto na camada TOPOGRAFIA_PONTOS (padrão true)" },
        "rotular_pontos": { "type": "boolean", "description": "insere textos com a cota Z de cada ponto na camada TOPOGRAFIA_ROTULOS (padrão true)" },
        "incluir_quadro": { "type": "boolean", "description": "insere quadro com dados estatísticos e resumo do levantamento na camada TOPOGRAFIA_QUADRO (padrão true)" },
        "quadro_ponto": { "type": "array", "items": { "type": "number" }, "description": "[x,y] do canto superior esquerdo do quadro (padrão: à direita do levantamento)" },
        "so_estatisticas": { "type": "boolean", "description": "só devolve os números (cotas, área, curvas…) sem desenhar nada no desenho aberto" }
    });
    vec![
        def(
            "cad_topografia",
            "TOPOGRAFIA — processa nuvem de pontos (.xyz, .pts, .csv, .txt) e gera automaticamente o levantamento topográfico completo: malha triangular TIN (Delaunay 2D), curvas de nível mestras e secundárias interpoladas e suavizadas, borda externa do terreno, pontos cotados com elevação Z e quadro de resumo estatístico. Cria camadas padronizadas (TOPOGRAFIA_CURVAS_MESTRAS, TOPOGRAFIA_CURVAS_SECUNDARIAS, TOPOGRAFIA_TIN, TOPOGRAFIA_PONTOS, TOPOGRAFIA_ROTULOS, TOPOGRAFIA_BORDA, TOPOGRAFIA_QUADRO) em um único passo que pode ser desfeito com Ctrl+Z.",
            &topo,
            &[]
        ),
    ]
}

fn de_documento() -> Vec<Value> {
    let escala = json!({ "type": "number", "description": "denominador da escala (100 = 1:100). Com ela, TODAS as medidas da chamada (alturas, larguras) valem em mm de PAPEL e saem do tamanho certo na folha; sem ela valem as unidades do desenho" });
    let camada = json!({ "type": "string", "description": "camada (criada se não existir)" });
    vec![
        def("cad_tabela", "TABELA a partir de dados (quadro de curvas, pontos notáveis, desvios, legenda): grade com título, cabeçalho e linhas. `origem` = canto superior esquerdo. `colunas: [{titulo, largura, alinhamento: esquerda|centro|direita, decimais}]`, `linhas: [[…],…]` (números saem formatados pelas `decimais` da coluna). `blocos: N` quebra em N blocos lado a lado (mesmo cabeçalho). `grade`: todas | 5em5 | externa. Texto maior que a coluna encolhe (até 55 %) e avisa se ainda não cabe. Devolve caixa, linhas por bloco e avisos.", &json!({ "origem": pt(), "escala": escala, "titulo": { "type": "string" }, "colunas": { "type": "array", "items": { "type": "object" } }, "linhas": { "type": "array", "items": { "type": "array" } }, "altura_linha": { "type": "number", "description": "padrão 6" }, "altura_texto": { "type": "number", "description": "padrão 3" }, "blocos": { "type": "integer" }, "grade": { "type": "string", "enum": ["todas", "5em5", "externa"] }, "virgula": { "type": "boolean", "description": "vírgula decimal" }, "camada": camada, "cor": { "type": "string" } }), &["origem", "colunas", "linhas"]),
        def("cad_grafico", "GRÁFICO X×Y de séries de dados (alinhamento, superelevação, perfil, ripagem…). `origem` = canto inferior esquerdo da área de plotagem; `largura`/`altura` dela (mm de papel com `escala`); `eixo_x`/`eixo_y`: {de, ate, marcas (passo dos números), rotulo, decimais}; `series: [{pontos:[[x,y],…], estilo: linha|cruz|degrau, camada, cor, rotulos?:[texto por ponto]}]` (o que passa da caixa é recortado). Vários gráficos empilhados com o mesmo eixo X = várias chamadas com a mesma escala/largura/eixo_x. Devolve a escala (unidades por unidade de dado) e a área, para você ancorar anotações.", &json!({ "origem": pt(), "escala": escala, "largura": { "type": "number" }, "altura": { "type": "number" }, "eixo_x": { "type": "object" }, "eixo_y": { "type": "object" }, "series": { "type": "array", "items": { "type": "object" } }, "titulo": { "type": "string" }, "grade": { "type": "boolean" }, "altura_texto": { "type": "number", "description": "padrão 2,5" }, "virgula": { "type": "boolean" }, "camada": camada, "cor": { "type": "string" } }), &["origem", "largura", "altura", "eixo_x", "eixo_y"]),
        def("cad_detalhe", "DETALHE ampliado: copia a `janela` do modelo para um bloco `DETALHE-n` posto em `ponto` (canto inferior esquerdo da moldura), na `escala_detalhe` (20 = 1:20) estando o desenho na folha em `escala_folha` (ou `folha`: nº da folha inserida). Traz moldura, título e, com `malha: passo`, graduação com as coordenadas do MODELO original nas bordas. Retas são recortadas na janela; círculo, arco, texto e hachura só entram inteiros (os cortados são contados em `omitidos_por_cortar_a_janela`). Um passo de desfazer.", &json!({ "janela": janela(), "ponto": pt(), "escala_detalhe": { "type": "number" }, "escala_folha": { "type": "number" }, "folha": { "type": "integer" }, "titulo": { "type": "string" }, "malha": { "type": "number", "description": "passo da graduação, em unidades do desenho" }, "altura_texto": { "type": "number", "description": "mm de papel (padrão 2,5)" }, "camada": camada.clone() }), &["janela", "ponto", "escala_detalhe"]),
        def("cad_ao_longo", "COISAS AO LONGO DE UM EIXO (`eixo`: id de linha/polilinha/arco, ou `pontos`; `de`/`ate` = distâncias pelo comprimento do eixo, não pela corda). `modo: repetir` — uma `forma` (como em cad_criar, em coordenadas locais: x ao longo do eixo, y à esquerda) ou um `componente` {nome,…} a cada `passo`, girado com o eixo (dormentes, postes); `defasagem` desloca de lado. `modo: paralelas` — polilinhas a `distancias` [±d] (positivo = esquerda): trilhos, bordos, meio-fio. `modo: marcas` — traço + rótulo a cada `passo`: `rotulo: estaca|km|distancia|nenhum`, `progressiva_inicial` (m), `passo_estaca` (20), `rotular_a_cada`, `lado`; o texto nunca fica de cabeça para baixo. Um passo de desfazer; funciona dentro do cad_lote.", &json!({ "eixo": { "type": "integer" }, "pontos": { "type": "array", "items": pt() }, "de": { "type": "number" }, "ate": { "type": "number" }, "modo": { "type": "string", "enum": ["repetir", "paralelas", "marcas"] }, "passo": { "type": "number" }, "forma": { "type": "object" }, "componente": { "type": "object" }, "defasagem": { "type": "number" }, "rotacao": { "type": "number" }, "distancias": { "type": "array" }, "tamanho": { "type": "number", "description": "comprimento do traço da marca (mm de papel com `escala`; padrão 3)" }, "altura_texto": { "type": "number" }, "rotulo": { "type": "string" }, "progressiva_inicial": { "type": "number" }, "passo_estaca": { "type": "number" }, "rotular_a_cada": { "type": "integer" }, "lado": { "type": "string", "enum": ["esquerda", "direita"] }, "escala": escala.clone(), "camada": camada.clone(), "cor": { "type": "string" } }), &["modo"]),
        def("cad_malha_coordenadas", "MALHA DE COORDENADAS sobre uma `caixa` do desenho ([[x1,y1],[x2,y2]]): traços nas quatro bordas, rótulos (`rotulos`: E/N, xy ou nenhum) e cruzetas nas interseções (`cruzetas: false` = linhas finas) a cada `passo` (unidades do desenho). Medidas de texto em mm de papel com `escala`.", &json!({ "caixa": janela(), "passo": { "type": "number" }, "rotulos": { "type": "string" }, "cruzetas": { "type": "boolean" }, "altura_texto": { "type": "number" }, "escala": escala.clone(), "virgula": { "type": "boolean" }, "camada": camada.clone(), "cor": { "type": "string" } }), &["caixa", "passo"]),
        def("cad_fiacao", "PROJETO ELÉTRICO — FIAÇÃO DE QUADRO (vista frontal) como na montagem real: cada fio é uma polilinha em que TODA quina vira curva (`raio`, padrão 4 mm; encolhe sozinho em trecho curto) e a ponta que entra no borne leva ponteira (`ponteira_inicio`/`ponteira_fim`, padrão true). `condutor` R|S|T|N|PE|retorno → UMA CAMADA POR CONDUTOR (DI-Fio-Fase-R preto, -Fase-S vermelho, -Fase-T marrom, -Neutro azul, -Terra verde, -Retorno amarelo), criadas com cor e espessura: o usuário liga/desliga e escolhe imprimir por condutor. COMO TRAÇAR: o cabo chega ao borne do disjuntor na VERTICAL (por cima no borne de cima, por baixo no de baixo), anda pela canaleta em pistas paralelas (1 mm entre fios, nunca um por cima do outro), sobe pela lateral e sai pelo eletroduto; todo fio vai de um borne a outro, sem ponta solta. `bornes: [{origem (canto de baixo à esquerda), tipos: [R,N,PE…], rotulos, passo (6,2), altura (42)}]` desenha a RÉGUA DE BORNES de saída (camada DI-Bornes; faixa azul no neutro, verde no terra) e devolve `reguas[].bornes[].parafuso_topo/parafuso_base` para ligar os fios. `escala` como nas outras.", &json!({ "fios": { "type": "array", "items": { "type": "object", "properties": { "condutor": { "type": "string" }, "pontos": { "type": "array", "items": pt() }, "raio": { "type": "number" }, "ponteira_inicio": { "type": "boolean" }, "ponteira_fim": { "type": "boolean" } }, "required": ["pontos"] } }, "bornes": { "type": "array", "items": { "type": "object" } }, "raio": { "type": "number" }, "escala": escala.clone() }), &[]),
        def("cad_norte", "SÍMBOLO DO NORTE em `ponto`: `tipo: seta|rosa`, `tamanho` (mm de papel com `escala`; padrão 15) e `rotacao` (graus: declinação/quadrícula — o norte do símbolo é o do desenho girado).", &json!({ "ponto": pt(), "tipo": { "type": "string", "enum": ["seta", "rosa"] }, "tamanho": { "type": "number" }, "rotacao": { "type": "number" }, "escala": escala.clone(), "camada": camada.clone(), "cor": { "type": "string" } }), &["ponto"]),
        def("cad_projetar", "PROJEÇÃO 3D→2D: `camera` iso | obliqua | {azimute, elevacao (90 = topo, 0 = frente), escala}. `pontos3d: [[x,y,z],…]` devolve os pontos 2D; `linhas: [[[x,y,z],…],…]` DESENHA as polilinhas projetadas (em `origem`). Sem linhas ocultas. Use para blocos 3D e perspectivas em desenho 2D.", &json!({ "camera": {}, "pontos3d": { "type": "array" }, "linhas": { "type": "array" }, "origem": pt(), "camada": camada.clone(), "cor": { "type": "string" } }), &[]),
        def("cad_alinhamento", "TRAÇADO HORIZONTAL por PIs com curvas de transição (clotoide simétrica) ou circulares. `pis: [[E,N],…]` do início ao fim; `curvas`: UMA por PI interno, `{R, Ls}` (Ls 0 = circular simples) ou `null` onde não há curva. Devolve, por curva: Δ, lado, R, Ls, Lc, Ts, E, θs, A, p, k e TS/SC/CS/ST (estaca `117+12,66`, km, E, N), mais o comprimento total — e GUARDA o alinhamento sob `nome` (padrão A1) para cad_alinhamento_ponto e cad_superelevacao. Erros dizem o PI (curvas que se sobrepõem, Δ pequeno demais). `desenhar: {eixo, estacas, km, notaveis, rotulos}` (booleans) desenha nas camadas `<camada_base>_EIXO/_ESTACAS/_KM/_NOTAVEIS`; `escala` (mm de papel para textos/marcas), `rotular_estacas_a_cada` (5 = a cada 100 m), `progressiva_inicial` (m), `passo_estaca` (20).", &json!({ "pis": { "type": "array", "items": pt() }, "curvas": { "type": "array" }, "nome": { "type": "string" }, "progressiva_inicial": { "type": "number" }, "passo_estaca": { "type": "number" }, "desenhar": { "type": "object" }, "camada_base": { "type": "string" }, "escala": escala.clone(), "altura_texto": { "type": "number" }, "rotular_estacas_a_cada": { "type": "integer" }, "passo_amostra": { "type": "number", "description": "m entre vértices do eixo nas curvas (padrão 1)" }, "cor": { "type": "string" } }), &["pis", "curvas"]),
        def("cad_alinhamento_ponto", "Consulta o alinhamento guardado numa estaca: E, N, azimute, direção, curvatura, raio e elemento (T = tangente, E = espiral, C = circular) e a curva. Passe `progressiva` (m) ou `estaca` (`117+12,66`); `alinhamento` = nome (padrão: o último). Com `de`/`ate`/`passo` (m; padrão 5) devolve o TRAÇADO AMOSTRADO (progressiva, E, N, direção, curvatura, elemento, curva), em arquivo se longo (`salvar: true` força).", &json!({ "alinhamento": { "type": "string" }, "progressiva": { "type": "number" }, "estaca": { "type": "string" }, "de": { "type": "number" }, "ate": { "type": "number" }, "passo": { "type": "number" }, "salvar": { "type": "boolean" } }), &[]),
        def("cad_superelevacao", "SUPERELEVAÇÃO ferroviária por curva do alinhamento guardado: he = B·V²/(127R), h adotado (arredondado e limitado), insuficiência I, aceleração não compensada, R mínimo, comprimento mínimo da transição (L_min), Ls sugerido, V máxima, rampa efetiva, flecha e excesso a velocidade lenta, com ✔/✘ por critério — e o MEMORIAL em texto com os números de cada passo (pronto para cad_texto_bloco). `regras`: nome de tabela (ferrovia_metrica) ou objeto com o que muda ({B, V, h_max_mm, i_max_mm, dh_dt_mm_s, rampa, psi, ls_min, ls_multiplo, h_passo_mm}); `V` direto também vale. `Ls_auto: true` refaz o alinhamento com o Ls sugerido onde o atual é curto. Limites de fábrica = usuais de bitola métrica, NÃO conferidos na NBR 16961:2021.", &json!({ "alinhamento": { "type": "string" }, "regras": {}, "V": { "type": "number" }, "Ls_auto": { "type": "boolean" } }), &[]),
        def("cad_nuvem_secoes", "NUVEM DE PONTOS → SEÇÕES: lê `caminho` (.csv/.xyz/.pts/.txt com E,N,Z), rastreia o EIXO pela própria nuvem (`eixo: \"auto\"`, padrão; `inicio` [E,N] e `direcao` em graus se precisar) ou usa o `eixo` (id de uma polilinha), e dá cada ponto como estaca, afastamento (+ = esquerda) e cota. Guarda a nuvem na sessão (`nome`, padrão N1). Resultado grande vai para arquivo (resumo + caminho; `salvar: true` força).", &json!({ "caminho": { "type": "string" }, "nuvem": { "type": "string" }, "nome": { "type": "string" }, "eixo": {}, "inicio": pt(), "direcao": { "type": "number" }, "agrupar_m": { "type": "number", "description": "distância máxima entre pontos da mesma seção (padrão 3)" }, "salvar": { "type": "boolean" } }), &[]),
        def("cad_nuvem_feicoes", "FEIÇÕES da nuvem: com `tipo: trilhos`, acha em cada seção o par de trilhos (a `bitola` + 0,06 de eixo a eixo, ± `tolerancia`), e devolve o eixo existente (ponto médio), cota, nivelamento transversal (esquerdo − direito) e bitola medida, com estatísticas (mediana, p5/p95, lacunas, seções sem par). Guarda como `feicoes` (nome F1) para cad_nuvem_qualidade, cad_alinhamento_ajustar, cad_greide e cad_tabela_estacas, sem você copiar pontos. Com `tipo: bordos`: em cada seção, de cada lado, a crista da plataforma (fim da parte plana, `tolerancia_z` 0,15 da cota do eixo) e o pé do talude (`inclinacao_pe` 0,1), com `afastamento_max`, `buraco_m`, e `desenhar: true` traça as linhas em `BORDOS` (guarda só a lista, não vira `feicoes`). Lista longa vai para arquivo.", &json!({ "nuvem": { "type": "string" }, "caminho": { "type": "string" }, "nome": { "type": "string" }, "tolerancia_z": { "type": "number" }, "inclinacao_pe": { "type": "number" }, "buraco_m": { "type": "number" }, "desenhar": { "type": "boolean" }, "camada": { "type": "string" }, "tipo": { "type": "string", "enum": ["trilhos", "bordos"] }, "bitola": { "type": "number", "description": "entre faces internas, m (1,0 métrica; 1,6 larga; 1,435 padrão)" }, "eixo_a_eixo": { "type": "number" }, "tolerancia": { "type": "number" }, "afastamento_max": { "type": "number" }, "salvar": { "type": "boolean" } }), &[]),
        def("cad_nuvem_qualidade", "QUALIDADE das feições: cota fora da mediana local (> `desvio`, 0,3 m), lacunas (> `lacuna` m), pares com cotas IDÊNTICAS em série (nivelamento zero seguido: suspeita de cota copiada — a via pode parecer sem superelevação por isso) e densidade por 100 m. `marcar: true` desenha na camada INTERVENCAO. Os pares de cota suspeita ficam marcados para serem ignorados no ajuste.", &json!({ "feicoes": { "type": "string" }, "desvio": { "type": "number" }, "janela": { "type": "integer" }, "lacuna": { "type": "number" }, "serie": { "type": "integer" }, "marcar": { "type": "boolean" }, "camada": { "type": "string" }, "raio_marca": { "type": "number" } }), &[]),
        def("cad_alinhamento_ajustar", "AJUSTA o traçado ao EIXO EXISTENTE (de `feicoes`, ou `pontos`): acha os PIs (simplifica o eixo e junta vértices de mesmo sentido), estima os raios por ajuste de círculo e minimiza a ripagem mexendo nos PIs e raios (cada curva leva o Ls mínimo da superelevação; raios arredondados). Os pares de cota suspeita (cad_nuvem_qualidade) ficam de fora (`excluir_suspeitos`). Devolve o mesmo de cad_alinhamento + ripagem RMS e máxima, e guarda como `nome` (A1). Com `pis` (e `raios`) só refina o que você deu. `voltas` (3), `meta_rms` (0,25), `regras`, `arredondar_R` (5). Aceita `desenhar` como cad_alinhamento. Leva dezenas de segundos em eixos longos.", &json!({ "feicoes": { "type": "string" }, "pontos": {}, "pis": { "type": "array", "items": pt() }, "raios": { "type": "array", "items": { "type": "number" } }, "regras": {}, "V": { "type": "number" }, "voltas": { "type": "integer" }, "meta_rms": { "type": "number" }, "arredondar_R": { "type": "number" }, "tolerancia_dp": { "type": "number" }, "excluir_suspeitos": { "type": "boolean" }, "nome": { "type": "string" }, "desenhar": { "type": "object" }, "camada_base": { "type": "string" }, "escala": escala.clone() }), &[]),
        def("cad_greide", "GREIDE (perfil longitudinal) de projeto sobre o perfil existente (de `feicoes`, projetadas no alinhamento, ou `perfil_existente: [[estaca_m, cota],…]`): PIVs por simplificação, retas por mínimos quadrados, e com `regra: so_levante` (padrão) eleva até nenhum rebaixo passar de `rebaixo_max` (0,02 m); `minimos_quadrados` não levanta. Curvas verticais parabólicas de raio `Rv` (5000). Devolve PIVs (estaca, cota, rampas, Lv, tipo), rampas, levante mínimo/médio/máximo e a cota de projeto por estaca (`passo`, 20 m). Guarda como `nome` (G1). `rampa_max` só conta os trechos acima.", &json!({ "alinhamento": { "type": "string" }, "feicoes": { "type": "string" }, "perfil_existente": {}, "regra": { "type": "string", "enum": ["so_levante", "minimos_quadrados"] }, "rebaixo_max": { "type": "number" }, "tolerancia": { "type": "number" }, "Rv": { "type": "number" }, "rampa_max": { "type": "number" }, "passo": { "type": "number" }, "nome": { "type": "string" }, "salvar": { "type": "boolean" } }), &[]),
        def("cad_tin", "MALHA TRIANGULAR (TIN) e CURVAS DE NÍVEL da nuvem de pontos, só em DADOS (não desenha): grava um JSON com `pontos` [E,N,cota], `triangulos` (índices dos pontos) e `curvas` ({cota, mestra, fechada, pontos}) e devolve o caminho em `arquivo`. A nuvem vem de `caminho` ou de `nuvem` (nome na sessão; padrão a última lida). `equidistancia`, `passo_mestra`, `max_aresta` como em cad_topografia. É a mesma triangulação que o leitor de nuvem usa; serve para montar folhas (mapa da nuvem, plantas) com a superfície triangulada.", &json!({ "caminho": { "type": "string" }, "nuvem": { "type": "string" }, "equidistancia": { "type": "number" }, "passo_mestra": { "type": "integer" }, "max_aresta": { "type": "number" } }), &[]),
        def("cad_analise", "ANÁLISE DE CRITICIDADE do traçado: para cada CURVA (TS→ST) e cada TANGENTE devolve o nível (NORMAL, ATENÇÃO, CRÍTICO) com os motivos escritos (raio perto do mínimo, superelevação no limite, insuficiência, transição curta, ripagem grande, rampa, tangente curta…), o levante (greide − existente: + aterro, − escavação), a ripagem, as rampas, as cotas e as ZONAS de aterro e escavação com o valor máximo e onde. Devolve também os volumes estimados de terraplenagem e a curva de massa. Usa o alinhamento, o greide e as feições (`existente`, F1) da sessão; `criterios` muda os limiares (fracao_h, fracao_i, folga_r, folga_v, folga_ls, ripagem_atencao/critica, movimento_minimo/atencao/critico, rampa_atencao_pct/critica_pct, tangente_minima, largura_plataforma).", &json!({ "alinhamento": { "type": "string" }, "greide": { "type": "string" }, "existente": { "type": "string" }, "regras": {}, "V": { "type": "number" }, "criterios": { "type": "object" } }), &[]),
        def("cad_geografico", "UTM → latitude/longitude (graus decimais e graus-minutos-segundos), convergência de meridianos e fator de escala, para `pontos: [[E, N], …]` na `zona` UTM e `hemisferio` (sul padrão). SIRGAS 2000/WGS 84. A zona é uma premissa: confirme no levantamento.", &json!({ "pontos": { "type": "array", "items": pt() }, "zona": { "type": "integer" }, "hemisferio": { "type": "string", "enum": ["sul", "norte"] } }), &["pontos", "zona"]),
        def("cad_tabela_estacas", "TABELA POR ESTACA pronta: estaca, km, elemento (T/E/C), curva, h atual (do existente) e de projeto, flecha medida e de projeto, ripagem, cotas existente e de projeto e levante — calculadas do alinhamento + superelevação + greide + feições da sessão, sem você copiar números. `colunas` escolhe e ordena (estaca, km, elemento, curva, h_atual, h_projeto, flecha_medida, flecha_projetada, ripagem, cota_existente, cota_projeto, levante, E, N, curvatura, progressiva); `passo` (20), `so_curvas`. Com `desenhar_tabela: {origem, escala, titulo, blocos…}` já desenha com cad_tabela. Lista longa vai para arquivo.", &json!({ "alinhamento": { "type": "string" }, "greide": { "type": "string" }, "existente": { "type": "string" }, "regras": {}, "V": { "type": "number" }, "colunas": { "type": "array", "items": { "type": "string" } }, "passo": { "type": "number" }, "so_curvas": { "type": "boolean" }, "de": { "type": "number", "description": "progressiva inicial (m) do trecho" }, "ate": { "type": "number" }, "desenhar_tabela": { "type": "object" }, "salvar": { "type": "boolean" } }), &[]),
        def("cad_via", "SUPERESTRUTURA FERROVIÁRIA sobre o alinhamento guardado. `desenho: planta` (padrão) — 4 polilinhas de trilho (bordas do boleto, B ± largura do boleto) e dormentes a cada `dormente.espaco` ao longo do eixo (`de`/`ate` em metros do alinhamento; `destino {de:[x,y], para:[x,y], ampliacao, giro}` leva a planta para uma folha em outra escala; centenas de milhares de formas em eixo longo: use trechos). `desenho: secao` — seção tipo em `ponto`: trilhos, dormente inclinado pela superelevação (`h_mm`, ou a de `progressiva` conforme `regras`), lastro (`lastro`, `ombro`, `talude`), sublastro e textos. `bitola` (entre faces internas, 1,0), `B` (eixo a eixo; padrão bitola + 0,075, o do projeto de referência), `trilho` (\"TR-57\": arquivo `trilho_tr57` da biblioteca `ferrovia`; o do usuário em `~/.config/feathercad/biblioteca/` vale sobre o de fábrica, então outro perfil é só largar um `trilho_*.fct`), `boleto_mm` (padrão: o do perfil), `dormente` = nome (\"madeira\", \"concreto\": arquivos `dormente_*`) ou objeto `{tipo?, comprimento 2,0, largura 0,22, altura 0,20, espaco 0,60}` em metros sobre o padrão do arquivo, `ampliacao` (só seção).", &json!({ "alinhamento": { "type": "string" }, "desenho": { "type": "string", "enum": ["planta", "secao"] }, "bitola": { "type": "number" }, "B": { "type": "number" }, "boleto_mm": { "type": "number" }, "dormente": { "type": ["object", "string"] }, "trilho": { "type": "string" }, "destino": { "type": "object" }, "de": { "type": "number" }, "ate": { "type": "number" }, "dormentes": { "type": "boolean" }, "ponto": pt(), "h_mm": { "type": "number" }, "progressiva": { "type": "number" }, "regras": {}, "V": { "type": "number" }, "externo": { "type": "string", "enum": ["direito", "esquerdo"] }, "lastro": { "type": "number" }, "ombro": { "type": "number" }, "talude": { "type": "number" }, "sublastro": { "type": "number" }, "ampliacao": { "type": "number" }, "camada": camada.clone(), "camada_trilhos": { "type": "string" }, "camada_dormentes": { "type": "string" } }), &[]),
        def("cad_modelos", "Lista os MODELOS de projeto (um projeto inteiro a partir dos dados) e o `esquema` dos dados de cada um. Hoje: `ferrovia`.", &json!({}), &[]),
        def("cad_modelo", "Gera um PROJETO INTEIRO de uma chamada só a partir dos dados (veja cad_modelos). Modelos do usuário: um `.json` em `~/.config/feathercad/modelos/` (`{descricao, esquema, dados_padrao?, passos, retornar?}`, os passos são os de cad_lote) roda pelo nome com `dados` sobre `dados_padrao`. `nome: ferrovia`, `dados: {nuvem, V, bitola, regras, papel, escala, carimbo, saida}`: lê a nuvem de pontos, acha o eixo e os pares de trilho, marca suspeitos, ajusta o alinhamento com transições, calcula superelevação e greide, e monta as folhas (planta com detalhes das curvas críticas, gráficos e quadro de curvas, seção tipo e perspectiva, memorial, tabela por estaca). Roda em modo projeto: devolve só números e a verificação de leiaute — confira por folha com cad_ver {arquivo, janela}. Dezenas de segundos em linhas longas. Desfaz? Não (substitui o desenho aberto).", &json!({ "nome": { "type": "string", "enum": ["ferrovia"] }, "dados": { "type": "object" } }), &["nome", "dados"]),
        def("cad_texto_bloco", "PARÁGRAFOS com quebra automática pela largura (memorial, notas). `origem` = canto superior esquerdo; `itens: [{tipo: titulo|texto|formula|nota|lista, texto}]`; `colunas: N` (exige `altura_max`: onde passa para a coluna seguinte). Devolve `y_final` para encadear o próximo bloco e `estourou_altura_max`.", &json!({ "origem": pt(), "escala": escala, "largura": { "type": "number" }, "altura_texto": { "type": "number", "description": "padrão 3" }, "entrelinha": { "type": "number", "description": "múltiplo da altura (padrão 1,4)" }, "itens": { "type": "array", "items": { "type": "object" } }, "colunas": { "type": "integer" }, "altura_max": { "type": "number" }, "camada": camada, "cor": { "type": "string" } }), &["origem", "largura", "itens"]),
    ]
}

/// Todas as ferramentas, na ordem em que aparecem para a IA.
pub fn todas() -> Value {
    let mut v = de_arquivo();
    v.extend(de_consulta());
    v.extend(de_edicao());
    v.extend(de_lote());
    v.extend(de_eletrica());
    v.extend(de_topografia());
    v.extend(de_documento());
    Value::Array(v)
}
